import Image from "next/image";

/**
 * The Good Luck horseshoe mark (public/brand/mark.svg, generated by `bun run build-brand-icons`).
 * Served as a cached file rather than inlined so it adds nothing to first-load JS.
 * Decorative: it always sits beside the GOOD LUCK wordmark, which carries the name.
 */
export function BrandMark({ className, priority = false }: { className?: string; priority?: boolean }) {
  return (
    <Image
      src="/brand/mark.svg"
      alt=""
      width={40}
      height={40}
      unoptimized
      priority={priority}
      className={className}
    />
  );
}
